package run.ikaros.planning;
import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentOkrService implements OkrService { private final OkrCycleRepository cycles; private final OkrObjectiveRepository objectives; private final OkrKeyResultRepository keyResults; private final PlanningGoalRepository goals;
 public PersistentOkrService(OkrCycleRepository c,OkrObjectiveRepository o,OkrKeyResultRepository k,PlanningGoalRepository g){cycles=c;objectives=o;keyResults=k;goals=g;}
 public Mono<OkrCycleView> createCycle(UUID owner,CreateOkrCycleRequest r){if(!r.endAt().isAfter(r.startAt()))return Mono.error(new ConflictException("OKR 周期结束时间必须晚于开始时间"));Instant n=Instant.now();return cycles.save(new OkrCycleEntity(null,owner,r.name().trim(),r.startAt(),r.endAt(),OkrStatus.DRAFT,n,n,null)).map(this::cycle);}
 public Flux<OkrCycleView> cycles(UUID o){return cycles.findAllByOwnerIdOrderByStartAtDesc(o).map(this::cycle);}
 public Mono<OkrObjectiveView> createObjective(UUID owner,CreateOkrObjectiveRequest r){return cycle(owner,r.cycleId()).then(goal(owner,r.goalId())).then(Mono.defer(()->{Instant n=Instant.now();return objectives.save(new OkrObjectiveEntity(null,owner,r.cycleId(),r.title().trim(),r.description(),r.goalId(),OkrStatus.DRAFT,n,n,null)).map(this::objective);}));}
 public Flux<OkrObjectiveView> objectives(UUID o,UUID c){return cycle(o,c).thenMany(objectives.findAllByOwnerIdAndCycleIdOrderByCreatedAtDesc(o,c)).map(this::objective);}
 public Mono<OkrKeyResultView> createKeyResult(UUID owner,UUID id,CreateOkrKeyResultRequest r){return objective(owner,id).then(Mono.defer(()->{if(r.targetValue().equals(r.startValue()))return Mono.error(new ConflictException("KR 起点和目标不能相同"));Instant n=Instant.now();return keyResults.save(new OkrKeyResultEntity(null,owner,id,r.title().trim(),r.metricType(),r.startValue(),r.targetValue(),r.startValue(),OkrStatus.DRAFT,n,n,null)).map(this::keyResult);}));}
 public Flux<OkrKeyResultView> keyResults(UUID o,UUID id){return objective(o,id).thenMany(keyResults.findAllByOwnerIdAndObjectiveIdOrderByCreatedAtDesc(o,id)).map(this::keyResult);}
 private Mono<OkrCycleEntity> cycle(UUID o,UUID id){return cycles.findById(id).filter(x->x.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("OKR Cycle 不存在")));} private Mono<OkrObjectiveEntity> objective(UUID o,UUID id){return objectives.findById(id).filter(x->x.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Objective 不存在")));} private Mono<PlanningGoalEntity> goal(UUID o,UUID id){return id==null?Mono.empty():goals.findById(id).filter(x->x.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Goal 不存在")));}
 private OkrCycleView cycle(OkrCycleEntity x){return new OkrCycleView(x.id(),x.ownerId(),x.name(),x.startAt(),x.endAt(),x.status(),x.createdAt(),x.updatedAt(),x.version()==null?0:x.version());} private OkrObjectiveView objective(OkrObjectiveEntity x){return new OkrObjectiveView(x.id(),x.ownerId(),x.cycleId(),x.title(),x.description(),x.goalId(),x.status(),x.createdAt(),x.updatedAt(),x.version()==null?0:x.version());} private OkrKeyResultView keyResult(OkrKeyResultEntity x){return new OkrKeyResultView(x.id(),x.ownerId(),x.objectiveId(),x.title(),x.metricType(),x.startValue(),x.targetValue(),x.currentValue(),x.status(),x.createdAt(),x.updatedAt(),x.version()==null?0:x.version());}}
